  "occurrences": [
    {
      "file": "corpus/giron-d/sent/583.eml",
      "quote": "Please provide the top sheets relating to the following desk:  West Firm, \nNorth West Firm, Central Firm, Texas Intra-Month, and Central Intra-Month."
    },
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "In order for us to complete our monthly gas testing, please provide the \nfollowing items."
    },
    {
      "file": "corpus/giron-d/sent/515.eml",
      "quote": "Please provide us with the P&L top sheet as of October 31 for the following \nbooks."
    },
    {
      "file": "corpus/giron-d/sent/420.eml",
      "quote": "we have not received the P&L top pages \nor curve shift reports for the following regions:  West Firm, FT Northwest \nand Mgmt. West."
    },
    {
      "file": "corpus/giron-d/sent/326.eml",
      "quote": "We are requesting that you supply the P & L top pages for the \nlast day of the month for those regions that are applicable to you."
    },
    {
      "file": "corpus/giron-d/sent/201.eml",
      "quote": "Please make sure this guy gets what he needs."
    }
  ],
  "evidence": [
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "Additionally, if the majority of \nthe P&L pertains to curve shift, please provide the P&L top pages for five \nof  the  largest days including the Curve Shift Reports.",
      "note": "For curve-shift books the pull covers up to five days per book, not just one page. In this request it covered seven books over two months."
    },
    {
      "file": "corpus/giron-d/sent/516.eml",
      "quote": "Please get this info to me and I will pass it on to AA.",
      "note": "The request goes from AA to the controller, then to four book administrators, then back up. With a self-service folder these hand-offs disappear."
    },
    {
      "file": "corpus/giron-d/sent/583.eml",
      "quote": "Can you forward this to the appropriate book admin?",
      "note": "A second request for August P&L, sent in October. It shows the same chain, controller to book admin, and AA re-asking."
    },
    {
      "file": "corpus/giron-d/sent/420.eml",
      "quote": "Pull this together and then call Sharon so they can come get the copies.",
      "note": "Book admins print paper copies and AA comes to collect them. AA is still chasing third-quarter items in December."
    },
    {
      "file": "corpus/giron-d/sent/201.eml",
      "quote": "As of February 28th, Arthur Andersen employees will no longer have \naccess to Enron Lotus Notes.",
      "note": "The auditors' folder must be reachable from outside Lotus Notes."
    },
    {
      "file": "corpus/giron-d/sent/201.eml",
      "quote": "Once we \nhave reviewed these top pages, we will be contacting you to discuss the \ndrivers of these regions.",
      "note": "The talk about P&L drivers stays. Only the document pull is removed."
    }
  ],
  "stalls": [
    {
      "file": "corpus/giron-d/sent/317.eml",
      "quote": "Is there someone else that can direct us to?  I would like to get this \ninformation as soon as it is possible.",
      "note": "AA's testing waits because the controller who routes the request is away in Chicago until Thursday."
    },
    {
      "file": "corpus/giron-d/sent/420.eml",
      "quote": "Please provide this information as we would like to close \nout our third quarter file.",
      "note": "AA cannot close its third-quarter file until the missing top pages and curve-shift reports arrive."
    }
  ],
  "ongoing": true,
  "stated_rate": {
    "count": 1,
    "per": "month",
    "file": "corpus/giron-d/sent/201.eml",
    "quote": "As part of our monthly testing, we review the monthly Natural Gas P & L \nStatement"
  },
  "minutes": 150
}

